sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // 1. Admins and Placement Officers bypass restrictions
    if (gs.hasRole('admin') || gs.hasRole('x_snc_college_pl_0.placement_officer')) {
        return;
    }
    var userId = gs.getUserID();
    // 2. Check if the user is a student
    var appGr = new GlideRecord('x_snc_college_pl_0_application');
    appGr.addQuery('student.user', userId);
    appGr.query();

    if (appGr.getRowCount() > 0) {
        // Restrict students to their own applications
        current.addQuery('student.user', userId);
        return;
    }

    // 3. For Company HR: Instead of dot-walking across related tables (which causes ACL errors),
    // match records based on the direct company or drive reference field.
    // Replace 'company' with your actual field name pointing to the company or interviewer.
    var companyId = gs.getUser().getCompany(); 

    if (companyId) {
        // If your application table links directly to a company field:
        current.addQuery('company', companyId);

        // OR if you want them to see applications where they are the assigned interviewer:
        // current.addOrCondition('interviewer', userId);
    } else {
        // Fallback if no association is found
        current.addQuery('sys_id', 'none');
    }

})(current, previous);
